"use client";

import { useActionState } from "react";

type FormState = {
  success: boolean;
  message: string;
  errors?: {
    name?: string;
    email?: string;
    message?: string;
  };
};

async function submitContactForm(prevState: FormState, formData: FormData): Promise<FormState> {
  const name = formData.get("name") as string;
  const email = formData.get("email") as string;
  const message = formData.get("message") as string;

  const errors: FormState["errors"] = {};

  if (!name || name.trim() === "") {
    errors.name = "Name is required";
  }

  if (!email || email.trim() === "") {
    errors.email = "Email is required";
  }

  if (!message || message.trim() === "") {
    errors.message = "Message is required";
  }

  if (Object.keys(errors).length > 0) {
    return {
      success: false,
      message: "Please fix the errors below",
      errors,
    };
  }

  console.log("Contact form submitted:", { name, email, message });

  return {
    success: true,
    message: "Thank you for your message! We'll get back to you soon.",
  };
}

export default function ContactForm() {
  const [state, action, isPending] = useActionState(submitContactForm, {
    success: false,
    message: "",
  });

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={action}>
        <div>
          <label htmlFor="name">Name:</label>
          <input type="text" id="name" name="name" />
          {state.errors?.name && <p style={{ color: "red" }}>{state.errors.name}</p>}
        </div>
        <div>
          <label htmlFor="email">Email:</label>
          <input type="email" id="email" name="email" />
          {state.errors?.email && <p style={{ color: "red" }}>{state.errors.email}</p>}
        </div>
        <div>
          <label htmlFor="message">Message:</label>
          <textarea id="message" name="message" rows={4}></textarea>
          {state.errors?.message && <p style={{ color: "red" }}>{state.errors.message}</p>}
        </div>
        <button type="submit" disabled={isPending}>
          {isPending ? "Submitting..." : "Submit"}
        </button>
      </form>
      {state.message && (
        <p style={{ color: state.success ? "green" : "red" }}>{state.message}</p>
      )}
    </div>
  );
}
